"""After-cutoff decoys that are withdrawals (ledger or on-chain outflows) get deposit
wording in their memo or schedule comment ("came in ... credit pending", "arrived"),
contradicting the extract line and the schedule's 'out' direction."""
from collections import Counter
from icfr_agent_evals.dataset import build_cases
tally = Counter(); shown = 0
for split in ("dev", "ci"):
    for c in build_cases(split):
        t = c.truth
        for i in t.items:
            if i.role != "decoy" or "after_cutoff" not in t.eligibility(i).reasons or i.flow != "outflow":
                continue
            for ln in c.rendered.splitlines():
                if i.reference not in ln:
                    continue
                is_note = ln.startswith("  - ")
                is_row = ln.strip().startswith(i.reference + " |")
                if not (is_note or is_row):
                    continue
                text = ln.split(": ", 1)[1] if is_note else ln.rsplit(" | ", 1)[-1]
                if any(w in text for w in ("came in", "credit pending", "arrived")):
                    tally[(split, i.recorded_in)] += 1
                    if shown < 4:
                        shown += 1
                        print(t.case_id, i.reference, f"truth flow={i.flow} recorded_in={i.recorded_in}", "::", ln.strip()[-110:])
print(dict(tally), "total", sum(tally.values()))

