"""F4-realism-3: network fees on the chain extract are far outside what the chains
charge. Cardano's min fee is a*size + b with a = 44 lovelace/byte, b = 155,381
lovelace and max tx size 16,384 bytes (Shelley-era protocol parameters), so even a
maximum-size transaction costs about 0.876 ADA. A one-input one-output P2WPKH BTC
sweep is about 110 vB and a plain ETH transfer 21,000 gas."""
from decimal import Decimal
from collections import defaultdict
from icfr_agent_evals.dataset import build_cases
ADA_MAX_MIN_FEE = (Decimal(44) * 16384 + 155381) / Decimal(10**6)
fees = defaultdict(list)
for split in ("dev", "ci"):
    for c in build_cases(split):
        fx = c.fixture; mark = Decimal(fx["balances"]["mark"])
        for l in fx["onchain_extract"]["lines"]:
            if l.get("fee_units"):
                fees[fx["header"]["asset"]].append(Decimal(l["fee_units"]))
for a, v in sorted(fees.items()):
    v.sort(); med = v[len(v) // 2]
    extra = ""
    if a == "ADA":
        extra = f" | above max-size-tx min fee {ADA_MAX_MIN_FEE} ADA: {sum(x > ADA_MAX_MIN_FEE for x in v)}/{len(v)}"
    if a == "BTC":
        extra = f" | implied sat/vB at 110 vB: median {int(med * 10**8 / 110)}, min {int(v[0] * 10**8 / 110)}"
    if a == "ETH":
        extra = f" | implied gwei at 21,000 gas: median {med * 10**9 / 21000:.0f}, min {v[0] * 10**9 / 21000:.0f}"
    print(f"{a}: n={len(v)} fee min={v[0]} median={med} max={v[-1]}{extra}")

"""Post-cutoff decoy notes say an item 'came in ... credit pending' even when the
extract shows it as an outbound customer withdrawal."""
import re
from collections import Counter
from icfr_agent_evals.dataset import build_cases
cnt = Counter(); ex = []
for split in ('dev', 'ci'):
    for c in build_cases(split):
        fx = c.fixture
        dirs = {}
        for l in fx['onchain_extract']['lines']: dirs.setdefault(l['ref'], set()).add(l['dir'])
        for l in fx['ledger_extract']['lines']:
            if l['units'] and l['units'].startswith('-'): dirs.setdefault(l['ref'], set()).add('OUT')
            elif l['units']: dirs.setdefault(l['ref'], set()).add('IN')
        for n in fx['notes']:
            m = re.match(r'(\S+) .* came in at .*credit pending', n['text'])
            if not m: continue
            ref = m.group(1); d = dirs.get(ref, set())
            kind = 'standard' if c.truth.case_kind == 'standard' else 'hard'
            tag = 'OUT (withdrawal)' if 'OUT' in d and 'IN' not in d else ('IN' if 'IN' in d else str(d))
            cnt[(kind, tag)] += 1
            if tag.startswith('OUT') and len(ex) < 3: ex.append((c.truth.case_id, n['text']))
print(dict(cnt)); [print(' ', e) for e in ex]
